package com.mytraining;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebChromeClient; import android.view.WindowManager;
public class MainActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b); getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON); WebView w=new WebView(this); w.getSettings().setJavaScriptEnabled(true); w.getSettings().setDomStorageEnabled(true); w.setWebChromeClient(new WebChromeClient()); setContentView(w); w.loadUrl("file:///android_asset/index.html");} }